
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_erf_gws_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe_erf_gws", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.026994441067297e+00, -3.945342813166581e+00, -3.831037924756004e+00, -3.672923807216108e+00, -3.457944447504391e+00, -3.172795630987885e+00, -2.807735522264701e+00, -2.363171737508681e+00, -1.857081786198728e+00, -1.322629122140561e+00, -7.954549348819996e-01, -4.580431423314539e-01, -3.654573026292505e-01, -2.672794396712784e-01, -1.425260214583824e-01, -4.053529897681296e-02, -4.520386969150402e-03, -1.778794575549888e-04, -1.723644848875946e-06, -2.405126964468146e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


